fscanf(STDIN, "%d %s", $n, $t);
// or read all input
// $input = explode(' ', trim(fgets(STDIN))); // might not handle newlines well if separate lines
// Better: read all tokens
$tokens = explode(' ', trim(stream_get_contents(STDIN)));
$n = (int)$tokens[0];
$t = $tokens[1];

for ($i = 2; $i <= $n; $i++) {
    if ($n % $i == 0) {
        $t = strrev(substr($t, 0, $i)) . substr($t, $i);
    }
}
echo $t;
?>
```
